/* 等价 C 语言参考：管程实现有界缓冲区（示意） */
#include <stdio.h>
#include <string.h>

typedef struct {
    int  buf[64], head, tail, count, cap;
    int  wait_prod[64], wait_prod_n;    /* notfull 等待队列（存放待生产数据）*/
    int  wait_cons;                     /* notempty 等待队列长度 */
    int  consumed[256], consumed_n;
} Monitor;

/* 管程初始化：只在创建时执行一次 */
void mon_init(Monitor *m, int cap) {
    m->head = m->tail = m->count = 0; m->cap = cap;
    m->wait_prod_n = 0; m->wait_cons = 0; m->consumed_n = 0;
}

/* 内部：尝试唤醒等待的生产者——缓冲区不满则放入队尾 */
static void signal_notfull(Monitor *m) {
    if (m->wait_prod_n > 0 && m->count < m->cap) {
        int x = m->wait_prod[0];
        for (int i = 1; i < m->wait_prod_n; i++) m->wait_prod[i-1] = m->wait_prod[i];
        m->wait_prod_n--;
        m->buf[m->tail] = x; m->tail = (m->tail + 1) % m->cap; m->count++;
    }
}

/* 内部：尝试唤醒等待的消费者——缓冲区非空则取出队首 */
static void signal_notempty(Monitor *m) {
    if (m->wait_cons > 0 && m->count > 0) {
        m->consumed[m->consumed_n++] = m->buf[m->head];
        m->head = (m->head + 1) % m->cap; m->count--;
        m->wait_cons--;
    }
}

/* 管程过程 produce：满则 notfull.wait()，否则入缓冲区；随后 notempty.signal() */
void produce(Monitor *m, int data) {
    if (m->count >= m->cap) {
        m->wait_prod[m->wait_prod_n++] = data;   /* 进入等待 */
    } else {
        m->buf[m->tail] = data; m->tail = (m->tail + 1) % m->cap; m->count++;
    }
    signal_notfull(m);
    signal_notempty(m);
}

/* 管程过程 consume：空则 notempty.wait()，否则取队首；随后 notfull.signal() */
void consume(Monitor *m) {
    if (m->count == 0) {
        m->wait_cons++;                          /* 进入等待 */
    } else {
        m->consumed[m->consumed_n++] = m->buf[m->head];
        m->head = (m->head + 1) % m->cap; m->count--;
    }
    signal_notfull(m);
    signal_notempty(m);
}

int main(void) {
    Monitor m; mon_init(&m, 2);
    produce(&m, 'A'); produce(&m, 'B'); produce(&m, 'C');
    consume(&m); consume(&m); consume(&m);
    for (int i = 0; i < m.consumed_n; i++) printf("%c ", m.consumed[i]);
    printf("| waited=%d\n", m.wait_prod_n + m.wait_cons);
    return 0;
}

