def solve(ops, capacity):
    """管程实现有界缓冲区：单线程按顺序模拟管程（管程天然互斥）。

    ops: 操作序列，元素为 ["produce", data] 或 ["consume"]。
    capacity: 缓冲区容量。
    返回: {"consumed": [...], "buffer": [...], "waited": int}
    """
    buffer = []            # 管程内的共享缓冲区
    wait_producers = []    # 条件变量 notfull 的等待队列（存待生产数据）
    wait_consumers = []    # 条件变量 notempty 的等待队列
    consumed = []

    for op in ops:
        kind = op[0]
        if kind == "produce":
            data = op[1]
            if len(buffer) >= capacity:
                wait_producers.append(data)   # notfull.wait()
            else:
                buffer.append(data)
        elif kind == "consume":
            if not buffer:
                wait_consumers.append(1)      # notempty.wait()
            else:
                consumed.append(buffer.pop(0))

        # 每次操作后，先尽量唤醒等待的生产者，再尽量唤醒等待的消费者
        while wait_producers and len(buffer) < capacity:
            buffer.append(wait_producers.pop(0))
        while wait_consumers and buffer:
            consumed.append(buffer.pop(0))
            wait_consumers.pop(0)

    return {
        "consumed": consumed,
        "buffer": buffer,
        "waited": len(wait_producers) + len(wait_consumers),
    }
